use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Something that implements `HashStable<CTX>` can be hashed in a way that is"] # [doc = " stable across multiple compilation sessions."] # [doc = ""] # [doc = " Note that `HashStable` imposes rather more strict requirements than usual"] # [doc = " hash functions:"] # [doc = ""] # [doc = " - Stable hashes are sometimes used as identifiers. Therefore they must"] # [doc = "   conform to the corresponding `PartialEq` implementations:"] # [doc = ""] # [doc = "     - `x == y` implies `hash_stable(x) == hash_stable(y)`, and"] # [doc = "     - `x != y` implies `hash_stable(x) != hash_stable(y)`."] # [doc = ""] # [doc = "   That second condition is usually not required for hash functions"] # [doc = "   (e.g. `Hash`). In practice this means that `hash_stable` must feed any"] # [doc = "   information into the hasher that a `PartialEq` comparison takes into"] # [doc = "   account. See [#49300](https://github.com/rust-lang/rust/issues/49300)"] # [doc = "   for an example where violating this invariant has caused trouble in the"] # [doc = "   past."] # [doc = ""] # [doc = " - `hash_stable()` must be independent of the current"] # [doc = "    compilation session. E.g. they must not hash memory addresses or other"] # [doc = "    things that are \"randomly\" assigned per compilation session."] # [doc = ""] # [doc = " - `hash_stable()` must be independent of the host architecture. The"] # [doc = "   `StableHasher` takes care of endianness and `isize`/`usize` platform"] # [doc = "   differences."] pub trait HashStable < CTX > { fn hash_stable (& self , hcx : & mut CTX , hasher : & mut StableHasher) ; }